INSERT INTO `crs_tabledata1532` VALUES ('950', '{BD644721-8939-4671-BE7F-D9F3CB57ADF2}', '66', 'INHE-0634', '2018-12-05 09:19:32', '0000-00-00 00:00:00', '2019-06-25 14:42:48', 'unchecked', 'n', 'n', '', '1', 'lxdj2018120502/VIC', '', '1', 'LoraWAN通讯三相智能电表', '', '', '电表技术需求：1.	3x220/380V。2.	基表功能几乎无要求，满足有功1.0级, 无功2.0级，每日能够定时主动上报2~3次数据（默认：日冻结），868 MHz LoRaWAN通讯，数据帧格式无要求，客户目的是想要的LoRaWAN通讯技术的电表应用，而非电表本身。3.	电表（包含LoRaWAN模块）可以直接通过友讯达的gateway上传数据到任何公共服务器等，可以在Public Server上就能看到表主动上报的数据。4.	不需要表厂供系统，表厂提供电表（包括模块），友讯达提供网关，实现到LoRaWAN通讯到Public Server。5.	15分钟曲线数据上报，暂时可以不用做，上报日冻结数据就可以。', '5000', '{BD64472189394671BE7FD9F3CB57ADF2B6D2E2F5417D4A5DABC46AAC206790E4}_Smart Three Phase Energy Meter requirements.pdf');
INSERT INTO `crs_tabledata1532` VALUES ('951', '{97E31841-D165-4A4A-B5AE-D644B82D76CC}', '61', 'INHE-0500', '2018-12-06 01:53:05', '0000-00-00 00:00:00', '2018-12-07 18:29:54', 'unchecked', 'n', 'n', '', '1', 'lxdj2018120601/KWA', '', '0', '三年期框架采购合同：1.供应、安装和维护托管性质的STS售电系统；2.供应、安装和维护项目实施所涉及的硬件部分；3.负责和当前市政公司使用的第三方系统做接口。', '待和NYC协商', '', '', null, '{97E31841D1654A4AB5AED644B82D76CCB6D2E2F5417D4A5DABC46AAC206790E4}_KWA招标文件.pdf');
