INSERT INTO `crs_tabledata1532` VALUES ('1665', '{BCFE3158-696C-4DAE-BAF6-EDECF5C59A10}', '60', 'INHE-0881', '2019-12-09 15:58:36', '0000-00-00 00:00:00', '2019-12-12 14:53:28', 'unchecked', 'n', 'n', '', '1', 'lxdj2019120901/GMS', '', '0', '目前和代理处在一个战略合作的阶段，具体产品需求会在和电力公司以及能源部会面之后进行确认。右边附件为合作备忘录MOU，代理在条款5提出排他性条款。主要原因如下：第一，代理在之前负责的油田和矿业项目上都有排他性条款。第二，代理在哈萨克人脉资源丰富，可以安排我们与能源部和电力公司高层会面，并不是完全阻止我们和电力公司接触。第三，代理担心我们会面之后私下和电力公司联系，代理之前有经历过这种情况。第四，排他性有效期为1年，期限过后不受此条款约束。', '', '', '', null, '{BCFE3158696C4DAEBAF6EDECF5C59A10B6D2E2F5417D4A5DABC46AAC206790E4}_哈萨克斯坦MOU_V4.docx');
